150→// ─── Loader ───────────────────────────────────────────────────────────────────
151→
152→export const loader = async ({ request }: LoaderFunctionArgs) => {
153→  const { session } = await authenticate.admin(request);
154→  const shop = session.shop;
155→  const subscription = await getShopSubscription(shop);
156→  const isDev = process.env.NODE_ENV !== "production";
157→  return { subscription, isDev };
158→};
159→
160→// ─── Action ───────────────────────────────────────────────────────────────────
161→
162→export const action = async ({ request }: ActionFunctionArgs): Promise<
163→  | { error: string }
164→  | { success: boolean; message: string }
165→  | null
166→> => {
167→  const { session, billing } = await authenticate.admin(request);
168→  const shop = session.shop;
169→  const formData = await request.formData();
170→  const intent = String(formData.get("intent"));
171→
172→  if (intent === "subscribe") {
173→    const plan = String(formData.get("plan"));
174→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
175→    try {
176→      /* eslint-disable @typescript-eslint/no-explicit-any */
177→      await billing.request({
178→        plan: plan as any,
179→        isTest: process.env.NODE_ENV !== "production",
180→        returnUrl,
181→      });
182→      /* eslint-enable @typescript-eslint/no-explicit-any */
183→      return null;
184→    } catch (error) {
185→      if (error instanceof Response) throw error;
186→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
187→      const details = errorData?.map((e) => e.message).join(", ");
188→      const message = details || (error instanceof Error ? error.message : String(error));
189→
190→      if (message.includes("Custom apps cannot use the Billing API")) {
191→        return {
192→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
193→        };
194→      }
195→      return {
196→        error: `Failed to initiate subscription: ${message}`,
197→      };
198→    }
199→  }
200→
201→  if (intent === "test-set-plan") {
202→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
203→    const validTiers = ["free", "starter", "pro", "ultimate"];
204→    if (!validTiers.includes(tier)) {
205→      return { error: `Invalid plan tier: ${tier}` };
206→    }
207→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
208→    await db.subscription.upsert({
209→      where: { shop },
210→      create: { shop, planId, billingInterval: "monthly", status: "active" },
211→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
212→    });
213→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
214→  }
215→
216→  if (intent === "cancel") {
217→    try {
218→      const sub = await getShopSubscription(shop);
219→      if (sub.shopifySubscriptionId) {
220→        await billing.cancel({
221→          subscriptionId: sub.shopifySubscriptionId,
222→          isTest: process.env.NODE_ENV !== "production",
223→          prorate: true,
224→        });
225→      }
226→      await cancelShopSubscription(shop);
227→      return {
228→        success: true,
229→        message: "Subscription cancelled. You are now on the Free plan.",
230→      };
231→    } catch {
232→      return { error: "Failed to cancel subscription. Please try again." };
233→    }
234→  }
235→
236→  return null;
237→};
