 75→
 76→// ---------------------------------------------------------------------------
 77→// Action
 78→// ---------------------------------------------------------------------------
 79→
 80→export const action = async ({ request }: ActionFunctionArgs) => {
 81→  const { session } = await authenticate.admin(request);
 82→  const shop = session.shop;
 83→
 84→  const formData = await request.formData();
 85→  const intent = formData.get("intent") as string;
 86→
 87→  try {
 88→    if (intent === "save-behavior") {
 89→      const defaultBehavior = formData.get("defaultBehavior") as string;
 90→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 91→        return { error: "Invalid value for defaultBehavior" };
 92→      }
 93→      await db.shopSettings.upsert({
 94→        where: { shop },
 95→        create: { shop, defaultBehavior },
 96→        update: { defaultBehavior },
 97→      });
 98→      return { success: true, intent };
 99→    }
100→
101→    if (intent === "save-notification") {
102→      const notificationEmail =
103→        (formData.get("notificationEmail") as string | null) ?? "";
104→      await db.shopSettings.upsert({
105→        where: { shop },
106→        create: { shop, notificationEmail: notificationEmail || null },
107→        update: { notificationEmail: notificationEmail || null },
108→      });
109→      return { success: true, intent };
110→    }
111→
112→    if (intent === "save-email-settings") {
113→      const emailSenderName =
114→        (formData.get("emailSenderName") as string | null)?.trim() || null;
115→      const emailReplyTo =
116→        (formData.get("emailReplyTo") as string | null)?.trim() || null;
117→      await db.shopSettings.upsert({
118→        where: { shop },
119→        create: { shop, emailSenderName, emailReplyTo },
120→        update: { emailSenderName, emailReplyTo },
121→      });
122→      return { success: true, intent };
123→    }
124→
125→    if (intent === "send-test-email") {
126→      const testEmail = (formData.get("testEmail") as string | null) ?? "";
127→      if (!testEmail) return { error: "No email address provided." };
128→      const settings = await db.shopSettings.findUnique({ where: { shop } });
129→      const sent = await sendTestEmail(
130→        testEmail,
131→        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
132→        shop,
133→      );
134→      return sent
135→        ? { success: true, intent }
136→        : { error: "Failed to send test email. Check your Resend API key and sender email." };
137→    }
138→
139→    return { error: "Unknown intent" };
140→  } catch {
141→    return { error: "Failed to save settings. Please try again." };
142→  }
143→};
